var data = typeof payload === 'string' ? JSON.parse(payload) : JSON.parse(String.fromCharCode.apply(null, payload));
var deviceName = metadata.topic.split('/')[0];

if (deviceName.indexOf('shelly1pmminig3-') !== 0) {
    return null;
}

var result = {
    deviceName: deviceName,
    deviceType: 'Shelly 1PM Mini Gen3',
    telemetry: {}
};

result.telemetry = {
    estado_salida:       data.output,
    potencia_activa:     data.apower,
    voltaje:             data.voltage,
    corriente:           data.current,
    factor_potencia:     data.pf,
    frecuencia:          data.freq,
    energia_acumulada:   data.aenergy ? data.aenergy.total : null,
    energia_devuelta:    data.ret_aenergy ? data.ret_aenergy.total : null,
    temperatura_interna: data.temperature ? data.temperature.tC : null
};

return result;
